from pathlib import Path
import json
bank=[]
def add(id,subject,topic,prompt,choices,explanation,**kw):
    shift=len(bank)%5; choices=choices[shift:]+choices[:shift]; answer=(5-shift)%5+1
    bank.append(dict(id=id,subject=subject,topic=topic,question=prompt,choices=choices,answer=answer,explanation=explanation,difficulty='하',year=None,session=None,type='original',sourceUrl='https://github.com/YunSangYeong/Licensed-Real-Estate-Agent-CBT',verificationStatus='reviewed',reviewNote='자체 작성·내부 정답/문장 검토. 외부 전문가 검수·공식 출제기준 대조 미완료. 수치형 독립 재계산 테스트. 링크는 작성 기록이며 외부 정답 증빙이 아님.',version='main',rights='자체 작성 CC BY 4.0; 표시: Licensed-Real-Estate-Agent-CBT contributors. 외부 기출 없음.',**kw))
